-- MailChat - complete database setup, in one file.
--
-- Paste this entire file into the Supabase SQL editor and run it once. It is the
-- SQL from supabase/migrations/0001..0004, in order, plus a health check at the
-- end. Safe on a database in any state: empty, half-applied, or complete.
--
-- Why this exists: the migrations must be applied in order and re-run after a
-- failure, and doing that by hand from separate files goes wrong easily - a
-- half-applied file, a stale copy, a step missed. This removes the choices.
--
-- GENERATED by tool/check_migrations.dart --write-apply-all. Do not edit;
-- change supabase/migrations/*.sql or supabase/verify.sql and regenerate.
--
-- The last statement prints a verification table. Every row must read ok.

-- ==========================================================================
-- 0001_core_schema.sql
-- ==========================================================================

-- Safe to re-run. Every object is created only if absent, and every trigger is
-- dropped first: `create trigger` has no `if not exists`, so without the drop a
-- second run aborts the whole file with 42710.
-- ============================================================================
-- MailChat — 0001 core schema
-- ----------------------------------------------------------------------------
-- Email-based identity: every row is owned by an auth.users id. No phone
-- numbers, SMS or SIM data exist anywhere in this schema.
--
-- Apply with the Supabase CLI:
--   supabase db push
-- or paste into the SQL editor in dependency order.
-- ============================================================================

create extension if not exists "pgcrypto";

-- ----------------------------------------------------------------------------
-- Utility: keep updated_at accurate without trusting the client
-- ----------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- ============================================================================
-- profiles
-- One row per auth user. Username is the human-facing handle; email lives in
-- auth.users and is never exposed through this table.
-- ============================================================================
create table if not exists public.profiles (
  id           uuid primary key references auth.users (id) on delete cascade,
  username     text not null,
  display_name text not null default '',
  avatar_path  text,
  bio          text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),

  constraint profiles_username_format
    check (username ~ '^[a-z0-9][a-z0-9_.]{2,29}$'),
  constraint profiles_display_name_length
    check (char_length(display_name) <= 60),
  constraint profiles_bio_length
    check (bio is null or char_length(bio) <= 500)
);

-- Case-insensitive uniqueness: usernames are stored lowercased, but enforce
-- it defensively at the database level too.
create unique index if not exists profiles_username_lower_idx
  on public.profiles (lower(username));

drop trigger if exists profiles_set_updated_at on public.profiles;
create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- ============================================================================
-- conversations
-- ============================================================================
create table if not exists public.conversations (
  id          uuid primary key default gen_random_uuid(),
  type        text not null check (type in ('direct', 'group')),
  name        text,
  description text,
  avatar_path text,
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

drop trigger if exists conversations_set_updated_at on public.conversations;
create trigger conversations_set_updated_at
  before update on public.conversations
  for each row execute function public.set_updated_at();

create index if not exists conversations_updated_at_idx
  on public.conversations (updated_at desc);

-- ============================================================================
-- conversation_members
-- ============================================================================
create table if not exists public.conversation_members (
  conversation_id       uuid not null references public.conversations (id) on delete cascade,
  user_id               uuid not null references public.profiles (id) on delete cascade,
  role                  text not null default 'member'
                          check (role in ('member', 'admin', 'owner')),
  joined_at             timestamptz not null default now(),
  last_read_message_id  uuid,
  notifications_muted   boolean not null default false,
  muted_until           timestamptz,

  primary key (conversation_id, user_id)
);

create index if not exists conversation_members_user_idx
  on public.conversation_members (user_id);

-- ============================================================================
-- messages
-- ============================================================================
create table if not exists public.messages (
  id                  uuid primary key default gen_random_uuid(),
  conversation_id     uuid not null references public.conversations (id) on delete cascade,
  sender_id           uuid not null references public.profiles (id) on delete cascade,
  type                text not null default 'text'
                        check (type in ('text','image','video','audio','voice','file','system')),
  text                text,
  reply_to_message_id uuid references public.messages (id) on delete set null,
  client_id           text,
  created_at          timestamptz not null default now(),
  edited_at           timestamptz,
  deleted_at          timestamptz,

  constraint messages_text_present
    check (deleted_at is not null or type <> 'text' or (text is not null and char_length(text) > 0)),
  constraint messages_text_length
    check (text is null or char_length(text) <= 4000)
);

create index if not exists messages_conversation_created_idx
  on public.messages (conversation_id, created_at desc);

create index if not exists messages_sender_idx
  on public.messages (sender_id);

-- Idempotent sends: a retried optimistic send cannot create duplicates.
create unique index if not exists messages_client_id_idx
  on public.messages (conversation_id, client_id)
  where client_id is not null;

-- ============================================================================
-- message_attachments
-- ============================================================================
create table if not exists public.message_attachments (
  id           uuid primary key default gen_random_uuid(),
  message_id   uuid not null references public.messages (id) on delete cascade,
  storage_path text not null,
  file_name    text not null,
  mime_type    text not null,
  file_size    bigint not null check (file_size > 0),
  width        integer,
  height       integer,
  duration_seconds integer,
  created_at   timestamptz not null default now()
);

create index if not exists message_attachments_message_idx
  on public.message_attachments (message_id);

-- ============================================================================
-- message_reactions
-- ============================================================================
create table if not exists public.message_reactions (
  id         uuid primary key default gen_random_uuid(),
  message_id uuid not null references public.messages (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  reaction   text not null check (char_length(reaction) between 1 and 16),
  created_at timestamptz not null default now(),

  -- One reaction of a given emoji per user per message.
  unique (message_id, user_id, reaction)
);

create index if not exists message_reactions_message_idx
  on public.message_reactions (message_id);

-- ============================================================================
-- message_receipts
-- ============================================================================
create table if not exists public.message_receipts (
  id           uuid primary key default gen_random_uuid(),
  message_id   uuid not null references public.messages (id) on delete cascade,
  recipient_id uuid not null references public.profiles (id) on delete cascade,
  delivered_at timestamptz,
  read_at      timestamptz,

  unique (message_id, recipient_id)
);

create index if not exists message_receipts_recipient_idx
  on public.message_receipts (recipient_id);

-- ============================================================================
-- user_blocks
-- ============================================================================
create table if not exists public.user_blocks (
  id              uuid primary key default gen_random_uuid(),
  blocker_id      uuid not null references public.profiles (id) on delete cascade,
  blocked_user_id uuid not null references public.profiles (id) on delete cascade,
  created_at      timestamptz not null default now(),

  unique (blocker_id, blocked_user_id),
  constraint user_blocks_no_self check (blocker_id <> blocked_user_id)
);

create index if not exists user_blocks_blocker_idx
  on public.user_blocks (blocker_id);

-- ============================================================================
-- user_reports
-- ============================================================================
create table if not exists public.user_reports (
  id               uuid primary key default gen_random_uuid(),
  reporter_id      uuid not null references public.profiles (id) on delete cascade,
  reported_user_id uuid not null references public.profiles (id) on delete cascade,
  message_id       uuid references public.messages (id) on delete set null,
  reason           text not null,
  description      text,
  status           text not null default 'open'
                     check (status in ('open','reviewed','closed','dismissed')),
  created_at       timestamptz not null default now(),

  constraint user_reports_no_self check (reporter_id <> reported_user_id),
  constraint user_reports_description_length
    check (description is null or char_length(description) <= 2000)
);

create index if not exists user_reports_status_idx
  on public.user_reports (status, created_at desc);

-- ============================================================================
-- user_devices (push tokens)
-- ============================================================================
create table if not exists public.user_devices (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references public.profiles (id) on delete cascade,
  device_id      text not null,
  platform       text not null check (platform in ('ios','android','web')),
  push_token     text,
  last_active_at timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),

  unique (user_id, device_id)
);

drop trigger if exists user_devices_set_updated_at on public.user_devices;
create trigger user_devices_set_updated_at
  before update on public.user_devices
  for each row execute function public.set_updated_at();

-- ============================================================================
-- notification_preferences
-- ============================================================================
create table if not exists public.notification_preferences (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references public.profiles (id) on delete cascade,
  conversation_id   uuid references public.conversations (id) on delete cascade,
  messages_enabled  boolean not null default true,
  mentions_enabled  boolean not null default true,
  reactions_enabled boolean not null default true,
  muted             boolean not null default false,
  muted_until       timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create unique index if not exists notification_preferences_user_conversation_idx
  on public.notification_preferences (user_id, conversation_id)
  where conversation_id is not null;

create unique index if not exists notification_preferences_user_global_idx
  on public.notification_preferences (user_id)
  where conversation_id is null;

drop trigger if exists notification_preferences_set_updated_at on public.notification_preferences;
create trigger notification_preferences_set_updated_at
  before update on public.notification_preferences
  for each row execute function public.set_updated_at();

-- ==========================================================================
-- 0002_functions_triggers.sql
-- ==========================================================================

-- ============================================================================
-- MailChat — 0002 functions & triggers
-- ----------------------------------------------------------------------------
-- Server-side invariants that the client must never be trusted to enforce:
--   * profile creation is tied to auth.users
--   * only conversation members can post
--   * direct conversations are unique per member pair
--   * unread counts derive from members.last_read_message_id
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Auto-create a profile row when a user signs up.
-- ----------------------------------------------------------------------------
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_username text;
  v_display  text;
begin
  v_username := lower(coalesce(
    new.raw_user_meta_data ->> 'username',
    split_part(new.email, '@', 1)
  ));

  -- Sanitise to the allowed username character set. If the attempt collides,
  -- a numeric suffix keeps signup from failing outright.
  v_username := regexp_replace(v_username, '[^a-z0-9_.]', '', 'g');
  if v_username !~ '^[a-z0-9][a-z0-9_.]{2,29}$' then
    v_username := 'user_' || substr(replace(new.id::text, '-', ''), 1, 12);
  end if;

  if exists (select 1 from public.profiles p where lower(p.username) = v_username) then
    v_username := substr(v_username, 1, 20) || '_' ||
                  substr(replace(new.id::text, '-', ''), 1, 8);
  end if;

  v_display := coalesce(new.raw_user_meta_data ->> 'display_name', v_username);

  insert into public.profiles (id, username, display_name)
  values (new.id, v_username, v_display)
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ----------------------------------------------------------------------------
-- Atomic "get or create" direct conversation.
-- Prevents the race where two devices open the same 1:1 chat simultaneously.
-- ----------------------------------------------------------------------------
create or replace function public.get_or_create_direct_conversation(
  other_user_id uuid
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  me        uuid := auth.uid();
  existing  uuid;
  new_id    uuid;
begin
  if me is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if me = other_user_id then
    raise exception 'cannot message yourself' using errcode = '22023';
  end if;

  -- Serialise concurrent creations for this member pair.
  perform pg_advisory_xact_lock(
    hashtext(least(me::text, other_user_id::text) || ':' ||
             greatest(me::text, other_user_id::text))
  );

  select c.id into existing
  from public.conversations c
  join public.conversation_members m1
    on m1.conversation_id = c.id and m1.user_id = me
  join public.conversation_members m2
    on m2.conversation_id = c.id and m2.user_id = other_user_id
  where c.type = 'direct'
  limit 1;

  if existing is not null then
    return existing;
  end if;

  insert into public.conversations (type, created_by)
  values ('direct', me)
  returning id into new_id;

  insert into public.conversation_members (conversation_id, user_id, role)
  values (new_id, me, 'member'), (new_id, other_user_id, 'member');

  return new_id;
end;
$$;

revoke all on function public.get_or_create_direct_conversation(uuid) from public;
grant execute on function public.get_or_create_direct_conversation(uuid) to authenticated;

-- ----------------------------------------------------------------------------
-- Enforce: the sender must be an active member of the conversation.
-- ----------------------------------------------------------------------------
create or replace function public.enforce_message_sender_is_member()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (
    select 1 from public.conversation_members
    where conversation_id = new.conversation_id
      and user_id = new.sender_id
  ) then
    raise exception 'sender is not a member of this conversation'
      using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists messages_sender_member_check on public.messages;
create trigger messages_sender_member_check
  before insert on public.messages
  for each row execute function public.enforce_message_sender_is_member();

-- ----------------------------------------------------------------------------
-- Bump conversation.updated_at on new message (drives ordering).
-- ----------------------------------------------------------------------------
create or replace function public.touch_conversation_on_message()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.conversations
     set updated_at = now()
   where id = new.conversation_id;
  return new;
end;
$$;

drop trigger if exists messages_touch_conversation on public.messages;
create trigger messages_touch_conversation
  after insert on public.messages
  for each row execute function public.touch_conversation_on_message();

-- ----------------------------------------------------------------------------
-- Owner must always be a member with role 'owner'.
-- ----------------------------------------------------------------------------
create or replace function public.enforce_group_owner_membership()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.type = 'group' and new.created_by is not null then
    insert into public.conversation_members (conversation_id, user_id, role)
    values (new.id, new.created_by, 'owner')
    on conflict (conversation_id, user_id)
      do update set role = 'owner';
  end if;
  return new;
end;
$$;

drop trigger if exists conversations_ensure_owner on public.conversations;
create trigger conversations_ensure_owner
  after insert on public.conversations
  for each row execute function public.enforce_group_owner_membership();

-- ----------------------------------------------------------------------------
-- Blocking: a blocked user cannot insert messages into a direct conversation
-- with the blocker. Enforced server-side so a modified client cannot bypass it.
-- ----------------------------------------------------------------------------
create or replace function public.enforce_block_between_users()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if exists (
    select 1
    from public.conversation_members other
    join public.user_blocks b
      on b.blocker_id = other.user_id
     and b.blocked_user_id = new.sender_id
    where other.conversation_id = new.conversation_id
  ) then
    raise exception 'message blocked' using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists messages_block_check on public.messages;
create trigger messages_block_check
  before insert on public.messages
  for each row execute function public.enforce_block_between_users();

-- ==========================================================================
-- 0003_rls_policies.sql
-- ==========================================================================

-- ============================================================================
-- MailChat — 0003 row level security
-- ----------------------------------------------------------------------------
-- Every table is owner/member scoped. The mobile app ships only the anon key,
-- so these policies are the real authorization boundary: a modified client
-- cannot read or write another user's data.
--
-- Helper predicates are SECURITY DEFINER functions so policies do not recurse
-- into the tables they protect.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Helper predicates
-- ----------------------------------------------------------------------------
create or replace function public.is_conversation_member(cid uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from public.conversation_members
    where conversation_id = cid and user_id = auth.uid()
  );
$$;

create or replace function public.is_group_admin(cid uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from public.conversation_members
    where conversation_id = cid
      and user_id = auth.uid()
      and role in ('admin','owner')
  );
$$;

create or replace function public.is_group_owner(cid uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from public.conversation_members
    where conversation_id = cid
      and user_id = auth.uid()
      and role = 'owner'
  );
$$;

-- Blocks are bidirectional for visibility: if either party blocked the other,
-- they should not see each other's content.
create or replace function public.has_block_relation(other_user uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from public.user_blocks
    where (blocker_id = auth.uid() and blocked_user_id = other_user)
       or (blocker_id = other_user and blocked_user_id = auth.uid())
  );
$$;

grant execute on function public.is_conversation_member(uuid) to authenticated;
grant execute on function public.is_group_admin(uuid) to authenticated;
grant execute on function public.is_group_owner(uuid) to authenticated;
grant execute on function public.has_block_relation(uuid) to authenticated;

-- ----------------------------------------------------------------------------
-- Enable RLS everywhere. Default deny: no policy means no access.
-- ----------------------------------------------------------------------------
alter table public.profiles               enable row level security;
alter table public.conversations          enable row level security;
alter table public.conversation_members   enable row level security;
alter table public.messages               enable row level security;
alter table public.message_attachments    enable row level security;
alter table public.message_reactions      enable row level security;
alter table public.message_receipts       enable row level security;
alter table public.user_blocks            enable row level security;
alter table public.user_reports           enable row level security;
alter table public.user_devices           enable row level security;
alter table public.notification_preferences enable row level security;

-- ============================================================================
-- profiles
-- Readable by any authenticated user (needed for username search), writable
-- only by the owner. Email never lives here.
-- ============================================================================
drop policy if exists profiles_select on public.profiles;
create policy profiles_select on public.profiles
  for select to authenticated
  using (true);

drop policy if exists profiles_insert_own on public.profiles;
create policy profiles_insert_own on public.profiles
  for insert to authenticated
  with check (id = auth.uid());

drop policy if exists profiles_update_own on public.profiles;
create policy profiles_update_own on public.profiles
  for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

drop policy if exists profiles_delete_own on public.profiles;
create policy profiles_delete_own on public.profiles
  for delete to authenticated
  using (id = auth.uid());

-- ============================================================================
-- conversations
-- Visible to members only. Creation is allowed for the creator; membership
-- rows are added by the client (direct) or the owner trigger (group).
-- ============================================================================
drop policy if exists conversations_select_member on public.conversations;
create policy conversations_select_member on public.conversations
  for select to authenticated
  using (public.is_conversation_member(id));

drop policy if exists conversations_insert_creator on public.conversations;
create policy conversations_insert_creator on public.conversations
  for insert to authenticated
  with check (created_by = auth.uid());

drop policy if exists conversations_update_admin on public.conversations;
create policy conversations_update_admin on public.conversations
  for update to authenticated
  using (public.is_group_admin(id) or created_by = auth.uid())
  with check (public.is_group_admin(id) or created_by = auth.uid());

drop policy if exists conversations_delete_owner on public.conversations;
create policy conversations_delete_owner on public.conversations
  for delete to authenticated
  using (public.is_group_owner(id));

-- ============================================================================
-- conversation_members
-- A member can see the roster of their own conversations. Self-insert is
-- allowed when starting a direct chat; admins manage the rest.
-- ============================================================================
drop policy if exists conversation_members_select on public.conversation_members;
create policy conversation_members_select on public.conversation_members
  for select to authenticated
  using (public.is_conversation_member(conversation_id));

drop policy if exists conversation_members_insert_self on public.conversation_members;
create policy conversation_members_insert_self on public.conversation_members
  for insert to authenticated
  with check (user_id = auth.uid() or public.is_group_admin(conversation_id));

drop policy if exists conversation_members_update_own on public.conversation_members;
create policy conversation_members_update_own on public.conversation_members
  for update to authenticated
  using (user_id = auth.uid() or public.is_group_admin(conversation_id))
  with check (user_id = auth.uid() or public.is_group_admin(conversation_id));

drop policy if exists conversation_members_delete on public.conversation_members;
create policy conversation_members_delete on public.conversation_members
  for delete to authenticated
  using (user_id = auth.uid() or public.is_group_admin(conversation_id));

-- ============================================================================
-- messages
-- Members read. Authors write. Soft delete only (deleted_at), enforced by the
-- update policy: a sender may only set deleted_at/edited_at on their own rows.
-- ============================================================================
drop policy if exists messages_select_member on public.messages;
create policy messages_select_member on public.messages
  for select to authenticated
  using (public.is_conversation_member(conversation_id));

drop policy if exists messages_insert_member on public.messages;
create policy messages_insert_member on public.messages
  for insert to authenticated
  with check (
    sender_id = auth.uid()
    and public.is_conversation_member(conversation_id)
  );

drop policy if exists messages_update_sender on public.messages;
create policy messages_update_sender on public.messages
  for update to authenticated
  using (sender_id = auth.uid())
  with check (sender_id = auth.uid());

-- Hard deletes are reserved for the service role (moderation/moderation jobs).
-- Soft delete is the client path via UPDATE ... deleted_at.

-- ============================================================================
-- message_attachments
-- ============================================================================
drop policy if exists message_attachments_select on public.message_attachments;
create policy message_attachments_select on public.message_attachments
  for select to authenticated
  using (
    exists (
      select 1 from public.messages m
      where m.id = message_id and public.is_conversation_member(m.conversation_id)
    )
  );

drop policy if exists message_attachments_insert on public.message_attachments;
create policy message_attachments_insert on public.message_attachments
  for insert to authenticated
  with check (
    exists (
      select 1 from public.messages m
      where m.id = message_id
        and m.sender_id = auth.uid()
        and public.is_conversation_member(m.conversation_id)
    )
  );

drop policy if exists message_attachments_delete on public.message_attachments;
create policy message_attachments_delete on public.message_attachments
  for delete to authenticated
  using (
    exists (
      select 1 from public.messages m
      where m.id = message_id and m.sender_id = auth.uid()
    )
  );

-- ============================================================================
-- message_reactions
-- ============================================================================
drop policy if exists message_reactions_select on public.message_reactions;
create policy message_reactions_select on public.message_reactions
  for select to authenticated
  using (
    exists (
      select 1 from public.messages m
      where m.id = message_id and public.is_conversation_member(m.conversation_id)
    )
  );

drop policy if exists message_reactions_insert on public.message_reactions;
create policy message_reactions_insert on public.message_reactions
  for insert to authenticated
  with check (
    user_id = auth.uid()
    and exists (
      select 1 from public.messages m
      where m.id = message_id and public.is_conversation_member(m.conversation_id)
    )
  );

drop policy if exists message_reactions_delete on public.message_reactions;
create policy message_reactions_delete on public.message_reactions
  for delete to authenticated
  using (user_id = auth.uid());

-- ============================================================================
-- message_receipts
-- A recipient may only write their own receipt; senders can read receipts for
-- their own messages.
-- ============================================================================
drop policy if exists message_receipts_select on public.message_receipts;
create policy message_receipts_select on public.message_receipts
  for select to authenticated
  using (
    recipient_id = auth.uid()
    or exists (
      select 1 from public.messages m
      where m.id = message_id and m.sender_id = auth.uid()
    )
  );

drop policy if exists message_receipts_insert on public.message_receipts;
create policy message_receipts_insert on public.message_receipts
  for insert to authenticated
  with check (recipient_id = auth.uid());

drop policy if exists message_receipts_update on public.message_receipts;
create policy message_receipts_update on public.message_receipts
  for update to authenticated
  using (recipient_id = auth.uid())
  with check (recipient_id = auth.uid());

-- ============================================================================
-- user_blocks
-- ============================================================================
drop policy if exists user_blocks_select on public.user_blocks;
create policy user_blocks_select on public.user_blocks
  for select to authenticated
  using (blocker_id = auth.uid());

drop policy if exists user_blocks_insert on public.user_blocks;
create policy user_blocks_insert on public.user_blocks
  for insert to authenticated
  with check (blocker_id = auth.uid());

drop policy if exists user_blocks_delete on public.user_blocks;
create policy user_blocks_delete on public.user_blocks
  for delete to authenticated
  using (blocker_id = auth.uid());

-- ============================================================================
-- user_reports
-- Reporters can create and read their own reports. Triage is service-role only.
-- ============================================================================
drop policy if exists user_reports_insert on public.user_reports;
create policy user_reports_insert on public.user_reports
  for insert to authenticated
  with check (reporter_id = auth.uid());

drop policy if exists user_reports_select_own on public.user_reports;
create policy user_reports_select_own on public.user_reports
  for select to authenticated
  using (reporter_id = auth.uid());

-- ============================================================================
-- user_devices
-- ============================================================================
drop policy if exists user_devices_all_own on public.user_devices;
create policy user_devices_all_own on public.user_devices
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- ============================================================================
-- notification_preferences
-- ============================================================================
drop policy if exists notification_preferences_all_own on public.notification_preferences;
create policy notification_preferences_all_own on public.notification_preferences
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- ==========================================================================
-- 0004_views_storage_realtime.sql
-- ==========================================================================

-- ============================================================================
-- MailChat — 0004 conversation_list view, storage buckets, realtime
-- ----------------------------------------------------------------------------
-- The view powers the chat list screen. Postgres views run with the
-- privileges of the owner by default, which would bypass RLS — so this view is
-- declared `security_invoker` (Postgres 15+) so the caller's RLS applies.
-- ============================================================================

create or replace view public.conversation_list
with (security_invoker = true)
as
select
  c.id                     as conversation_id,
  m.user_id                as user_id,
  c.id                     as id,
  jsonb_build_object(
    'id', c.id,
    'type', c.type,
    'name', c.name,
    'description', c.description,
    'avatar_path', c.avatar_path,
    'created_by', c.created_by,
    'created_at', c.created_at,
    'updated_at', c.updated_at
  )                        as conversation,
  last_msg.text            as last_message_text,
  last_msg.created_at      as last_message_at,
  last_msg.sender_id       as last_message_sender_id,
  (
    select count(*)
    from public.messages um
    where um.conversation_id = c.id
      and um.created_at > coalesce(last_read.created_at, '-infinity'::timestamptz)
      and um.sender_id <> m.user_id
      and um.deleted_at is null
  )                        as unread_count,
  m.notifications_muted    as is_muted,
  other_profile            as other_participant,
  -- Tie-breaker for the chat list's ORDER BY. Postgres allows CREATE OR REPLACE
  -- VIEW to append columns only, so this must stay last.
  c.updated_at             as updated_at
from public.conversation_members m
join public.conversations c on c.id = m.conversation_id

-- Last visible message per conversation.
left join lateral (
  select msg.text, msg.created_at, msg.sender_id
  from public.messages msg
  where msg.conversation_id = c.id
    and msg.deleted_at is null
  order by msg.created_at desc
  limit 1
) last_msg on true

-- The read cursor row (so unread_count can compare timestamps).
left join lateral (
  select rm.created_at
  from public.messages rm
  where rm.id = m.last_read_message_id
) last_read on true

-- The other participant for direct conversations (null for groups).
left join lateral (
  select jsonb_build_object(
    'id', p.id,
    'username', p.username,
    'display_name', p.display_name,
    'avatar_path', p.avatar_path,
    'bio', p.bio,
    'created_at', p.created_at,
    'updated_at', p.updated_at
  ) as other_profile
  from public.conversation_members om
  join public.profiles p on p.id = om.user_id
  where om.conversation_id = c.id
    and om.user_id <> m.user_id
    and c.type = 'direct'
  limit 1
) other on true

where c.type = 'group' or other.other_profile is not null;

grant select on public.conversation_list to authenticated;

-- ============================================================================
-- Storage buckets
-- Private buckets; access is granted through signed URLs issued after the RLS
-- policy below confirms the caller may read the object.
-- ============================================================================
insert into storage.buckets (id, name, public)
values ('avatars', 'avatars', false), ('attachments', 'attachments', false)
on conflict (id) do nothing;

-- Avatars: any authenticated user can read; users write only their own folder.
drop policy if exists avatars_read on storage.objects;
create policy avatars_read on storage.objects
  for select to authenticated
  using (bucket_id = 'avatars');

drop policy if exists avatars_write_own on storage.objects;
create policy avatars_write_own on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists avatars_update_own on storage.objects;
create policy avatars_update_own on storage.objects
  for update to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- Attachments: path layout is attachments/<conversation_id>/<file>.
-- Only members of that conversation may read or upload.
drop policy if exists attachments_read_member on storage.objects;
create policy attachments_read_member on storage.objects
  for select to authenticated
  using (
    bucket_id = 'attachments'
    and public.is_conversation_member(
      nullif((storage.foldername(name))[1], '')::uuid
    )
  );

drop policy if exists attachments_write_member on storage.objects;
create policy attachments_write_member on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'attachments'
    and public.is_conversation_member(
      nullif((storage.foldername(name))[1], '')::uuid
    )
  );

-- ============================================================================
-- Realtime
-- Broadcast message changes to subscribed clients. RLS still applies to the
-- rows Postgres changes deliver.
-- ============================================================================
-- Adding a table that is already published raises 42710, so each is checked
-- first. Realtime delivery depends on this: without the publication, subscribed
-- clients never receive row changes.
do $$
declare
  t text;
begin
  foreach t in array array[
    'messages', 'message_reactions', 'message_receipts', 'conversation_members'
  ] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime'
        and schemaname = 'public'
        and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
exception
  when others then
    -- A missing publication (42704), or a project where the caller may not
    -- alter it. Neither should abort the migration: the schema is the point,
    -- realtime is an add-on. The notice names the exact cause.
    raise notice 'realtime publication not updated: % (%)', sqlerrm, sqlstate;
end $$;

-- Needed so DELETE events carry the old row identity.
alter table public.messages replica identity full;

-- ==========================================================================
-- 0005_email_discovery.sql
-- ==========================================================================

-- ============================================================================
-- MailChat — 0005 email discovery
-- ----------------------------------------------------------------------------
-- Adds "find a person by their email address" to user search.
--
-- Why this needs a function: emails live in auth.users, not public.profiles,
-- and they must stay there. public.profiles is readable by every authenticated
-- user (policy profiles_select using (true)), so putting an email column on it
-- would publish every address to every account. A SECURITY DEFINER function can
-- read auth.users and return only profile fields — the address is an input that
-- is matched against, never an output.
--
-- Matching rules:
--   * email       — exact, case-insensitive. Never a substring, so the endpoint
--                   cannot be used to enumerate addresses from fragments.
--   * username    — substring, case-insensitive, as before.
--   * display_name— substring, case-insensitive, as before.
--   * unverified addresses are not discoverable: otherwise anyone could
--     pre-register a colleague's address and be found in their place.
--   * users who blocked the caller, or whom the caller blocked, are excluded.
--   * the caller is excluded from their own results.
--
-- Both lookups are opt-out, matching how address-book style discovery works
-- everywhere else, and are controlled by two columns the owner can change from
-- Privacy settings.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Discoverability flags. Default true: an app whose whole identity model is
-- email is unusable if nobody can be found by default.
-- ----------------------------------------------------------------------------
alter table public.profiles
  add column if not exists discoverable_by_email boolean not null default true;

alter table public.profiles
  add column if not exists discoverable_by_username boolean not null default true;

comment on column public.profiles.discoverable_by_email is
  'Whether this user can be matched by their exact email address in search.';
comment on column public.profiles.discoverable_by_username is
  'Whether this user can be matched by username or display name in search.';

-- ----------------------------------------------------------------------------
-- search_users
--
-- Returns profile fields plus how the row matched, never the email itself.
-- p_limit is clamped so a caller cannot ask for the whole table.
-- ----------------------------------------------------------------------------
create or replace function public.search_users(
  p_query text,
  p_limit integer default 20
)
returns table (
  id           uuid,
  username     text,
  display_name text,
  avatar_path  text,
  created_at   timestamptz,
  updated_at   timestamptz,
  matched_by   text
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with q as (
    -- One normalised form for both matches. It is only ever compared to a full
    -- address with '=' below, which is what stops fragment enumeration.
    select nullif(btrim(lower(p_query)), '') as raw
  )
  select
    p.id,
    p.username,
    p.display_name,
    p.avatar_path,
    p.created_at,
    p.updated_at,
    case when u.email is not null and lower(u.email) = q.raw
         then 'email' else 'profile' end as matched_by
  from public.profiles p
  join auth.users u on u.id = p.id
  cross join q
  where q.raw is not null
    and p.id <> auth.uid()
    and not exists (
      select 1 from public.user_blocks b
      where (b.blocker_id = auth.uid() and b.blocked_user_id = p.id)
         or (b.blocker_id = p.id and b.blocked_user_id = auth.uid())
    )
    and (
      (
        p.discoverable_by_email
        and u.email_confirmed_at is not null
        and lower(u.email) = q.raw
      )
      or (
        p.discoverable_by_username
        and (
          p.username ilike '%' || q.raw || '%'
          or p.display_name ilike '%' || q.raw || '%'
        )
      )
    )
  order by
    -- An exact address match is what the user asked for; show it first.
    case when u.email is not null and lower(u.email) = q.raw then 0 else 1 end,
    p.username
  limit greatest(1, least(coalesce(p_limit, 20), 50));
$$;

comment on function public.search_users(text, integer) is
  'Profile search by username, display name, or exact email. Never returns the email.';

-- Postgres grants EXECUTE to PUBLIC on new functions, so revoke before granting
-- deliberately. Anonymous callers must not be able to probe for accounts.
revoke all on function public.search_users(text, integer) from public;
revoke all on function public.search_users(text, integer) from anon;
grant execute on function public.search_users(text, integer) to authenticated;

-- MailChat — database health check.
--
-- Paste into the Supabase SQL editor and run. Read-only: it changes nothing.
-- Every row must read ok; anything else names the file that did not apply.
--
-- This is also the tail of supabase/apply_all.sql, so a successful setup prints
-- the same table as its last step.
--
-- Run it after applying migrations, after a git pull that changed them, and
-- whenever the app reports a missing column, table or function.

-- ============================================================================
-- Verification — every row must read ok
-- ============================================================================

select '01. tables with row level security disabled' as check,
       coalesce(string_agg(tablename, ', '), 'ok') as result
from pg_tables
where schemaname = 'public' and not rowsecurity

union all
select '02. conversation_list.updated_at',
       case when exists (
         select 1 from information_schema.columns
         where table_schema = 'public'
           and table_name = 'conversation_list'
           and column_name = 'updated_at'
       ) then 'ok' else 'MISSING - 0004 did not apply' end

union all
select '03. tables in public',
       count(*)::text || ' ok'
from pg_tables where schemaname = 'public'

union all
select '04. functions',
       case when count(*) >= 8 then count(*)::text || ' ok'
            else count(*)::text || ' - expected at least 8' end
from pg_proc p
join pg_namespace n on n.oid = p.pronamespace
where n.nspname = 'public'

union all
select '05. storage buckets',
       case when count(*) = 2 then 'ok'
            else count(*)::text || ' - expected avatars and attachments' end
from storage.buckets where id in ('avatars', 'attachments')

union all
select '06. tables published for realtime',
       case when count(*) = 4 then 'ok'
            else count(*)::text || ' - expected 4' end
from pg_publication_tables
where pubname = 'supabase_realtime' and schemaname = 'public'

union all
select '08. email discovery columns (0005)',
       case when (
         select count(*) from information_schema.columns
         where table_schema = 'public'
           and table_name = 'profiles'
           and column_name in ('discoverable_by_email', 'discoverable_by_username')
       ) = 2 then 'ok' else 'MISSING - 0005 did not apply' end

union all
select '09. search_users function (0005)',
       case when exists (
         select 1 from pg_proc p
         join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public' and p.proname = 'search_users'
       ) then 'ok' else 'MISSING - 0005 did not apply: email search needs it' end

union all
select '07. policies on public tables',
       count(*)::text || ' ok'
from pg_policies where schemaname = 'public'
order by 1;
